<script setup>
import {computed,ref} from 'vue'
import {code as listings} from '../services/local-csp-code.mjs'
const props=defineProps({name:{type:String,required:true},phase:{type:String,default:'start'}}),copied=ref(false)
const code=computed(()=>listings[props.name]||[])
const line=computed(()=>{const aliases={reject:'move',wipeout:'wipeout',propagate:'propagate'};const key=aliases[props.phase]||props.phase;return Math.max(0,code.value.findIndex(x=>x.includes("'"+key+"'")))})
const tokens=row=>row.split(/('(?:[^'\\]|\\.)*'|\b(?:export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null|throw)\b|\b\d+(?:\.\d+)?\b)/g).filter(Boolean).map(text=>({text,kind:text.startsWith("'")?'string':/^(export|function|const|let|for|of|if|else|return|while|yield|continue|break|new|true|false|null|throw)$/.test(text)?'keyword':/^\d/.test(text)?'number':''}))
async function copy(){try{await navigator.clipboard.writeText(code.value.join('\n'));copied.value=true}catch{copied.value=false}}
</script>
<template><section class="search-trace-code"><div class="trace-code-bar"><h4>JavaScript · {{ name }} · Dòng {{ line+1 }}</h4><button type="button" @click="copy">{{ copied?'Đã chép mã':'Chép mã' }}</button></div><pre><code><span v-for="(t,j) in tokens(code[line]||'')" :key="j" :class="t.kind">{{ t.text }}</span></code></pre><details><summary>Xem toàn bộ hàm đang thực thi</summary><p>Hàm sinh trả trạng thái qua yield. snap sao chép dữ liệu để xem lại. Các hàm phụ kiểm tra đầu vào, tính chi phí và kiểm tra ràng buộc được dùng chung trong bộ giải. Lịch sử quan sát được lưu thêm cho nút Lùi, không dùng để suy ra độ phức tạp bộ nhớ của thuật toán.</p><pre><code><span v-for="(row,i) in code" :key="i" class="trace-row" :class="{active:i===line}"><span class="line-number" aria-hidden="true">{{ i+1 }}</span><span><span v-for="(t,j) in tokens(row)" :key="j" :class="t.kind">{{ t.text }}</span></span></span></code></pre></details></section></template>
<style scoped>
.search-trace-code{min-width:0;margin-top:20px}.trace-code-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.trace-code-bar h4{font:600 var(--fs-small)/1.7 var(--font-ui);overflow-wrap:anywhere}.search-trace-code button{min-height:44px;padding:8px;border:1px solid var(--control);border-radius:var(--radius);background:var(--paper);color:var(--ink);cursor:pointer}.search-trace-code pre{white-space:pre-wrap;overflow-wrap:anywhere;overflow:visible;padding:12px;border:1px solid var(--rule);border-radius:var(--radius);background:var(--paper);color:var(--ink);font:13px/1.8 var(--font-code)}.search-trace-code code{font:inherit}.trace-row{display:grid;grid-template-columns:3ch minmax(0,1fr);gap:8px}.trace-row.active{background:var(--tim-soft);border-left:3px solid var(--tim)}.line-number{user-select:none;color:var(--ink-2)}.keyword{color:var(--tim);font-weight:600}.string{color:var(--xanh)}.number{color:var(--do)}summary{min-height:44px;cursor:pointer}button:focus-visible,summary:focus-visible{outline:3px solid var(--tim);outline-offset:3px}
</style>
